function BentoCard({ children, className = '', title, desc, icon: Icon }: { children?: React.ReactNode, className?: string, title: string, desc: string, icon: any }) {
  return (
    <div className={`relative bg-[#0f0f0f] border border-white/5 rounded-[32px] overflow-hidden group hover:border-primary-500/30 transition-colors duration-500 flex flex-col justify-between ${className}`}>
      <div className="absolute inset-0 bg-gradient-to-br from-primary-500/0 via-primary-500/0 to-primary-500/10 opacity-0 group-hover:opacity-100 transition-opacity duration-500" />
      
      {/* Dynamic Background Content */}
      <div className="absolute inset-0 z-0">
        {children}
      </div>

      {/* Foreground Content */}
      <div className="relative z-10 p-8 sm:p-10 mt-auto bg-gradient-to-t from-[#0f0f0f] via-[#0f0f0f]/90 to-transparent pt-32 pointer-events-none">
        <div className="flex items-center gap-3 mb-4">
          <div className="w-10 h-10 rounded-xl bg-primary-500/10 border border-primary-500/20 flex items-center justify-center text-primary-500 group-hover:scale-110 group-hover:bg-primary-500 group-hover:text-white transition-all duration-300">
            <Icon className="w-5 h-5" />
          </div>
          <h3 className="text-2xl font-black text-white">{title}</h3>
        </div>
        <p className="text-slate-400 font-medium text-base leading-relaxed max-w-sm">
          {desc}
        </p>
      </div>
    </div>
  );
}

